INSERT INTO `t_dish` VALUES (1900000000000000001,'蒜蓉西兰花','蒜蓉西兰花',NULL,1,NULL,1,2,'清淡',1,8,8,0,'西兰花大火快炒，清淡，是一道很稳的家常下饭菜。','[{\"no\": 1, \"text\": \"西兰花洗净切好，大蒜切配齐备用。\"}, {\"no\": 2, \"text\": \"锅烧热倒油，下蒜末和姜片爆出香味。\"}, {\"no\": 3, \"text\": \"倒入西兰花大火翻炒至断生。\"}, {\"no\": 4, \"text\": \"加入大蒜，沿锅边淋入盐和蚝油，翻炒均匀。\"}, {\"no\": 5, \"text\": \"炒到入味即可出锅，别炒过头影响口感。\"}]','[\"盐\", \"蚝油\"]','[\"炒锅\"]','[\"锅要烧到微微冒烟再下菜，才有镬气。\", \"调料提前兑成碗汁，下锅不慌。\"]','[\"西兰花可以用同季的替代品，用量保持不变。\"]',72.50,6.80,0.90,10.50,2.50,633.30,2,1,4.15,26,0.6471,21,622,'2026-08-02 21:34:23',0,'2026-08-02 21:34:23','2026-10-02 01:40:23'),(1900000000000000006,'手撕包菜','手撕包菜',NULL,1,NULL,1,3,'酸辣',1,8,8,1,'白菜大火快炒，酸辣，是一道很稳的家常下饭菜。','[{\"no\": 1, \"text\": \"白菜洗净切好，干辣椒切配齐备用。\"}, {\"no\": 2, \"text\": \"锅烧热倒油，下蒜末和姜片爆出香味。\"}, {\"no\": 3, \"text\": \"倒入白菜大火翻炒至断生。\"}, {\"no\": 4, \"text\": \"加入干辣椒，沿锅边淋入生抽和醋，翻炒均匀。\"}, {\"no\": 5, \"text\": \"炒到入味即可出锅，别炒过头影响口感。\"}]','[\"生抽\", \"醋\", \"盐\"]','[\"炒锅\"]','[\"锅要烧到微微冒烟再下菜，才有镬气。\", \"调料提前兑成碗汁，下锅不慌。\"]','[\"白菜可以用同季的替代品，用量保持不变。\"]',41.00,2.70,0.40,7.10,1.80,538.40,2,1,4.17,46,0.7027,23,1305,'2026-08-07 21:41:57',0,'2026-08-07 21:41:57','2026-10-02 01:40:23'),(1900000000000000013,'干煸豆角','干煸豆角',NULL,1,NULL,1,3,'干香',2,10,15,1,'豆角大火快炒，干香，是一道很稳的家常下饭菜。','[{\"no\": 1, \"text\": \"豆角洗净切好，猪肉切配齐备用。\"}, {\"no\": 2, \"text\": \"锅烧热倒油，下蒜末和姜片爆出香味。\"}, {\"no\": 3, \"text\": \"倒入豆角大火翻炒至断生。\"}, {\"no\": 4, \"text\": \"加入猪肉，沿锅边淋入生抽和盐，翻炒均匀。\"}, {\"no\": 5, \"text\": \"炒到入味即可出锅，别炒过头影响口感。\"}]','[\"生抽\", \"盐\", \"干辣椒\"]','[\"炒锅\"]','[\"锅要烧到微微冒烟再下菜，才有镬气。\", \"调料提前兑成碗汁，下锅不慌。\"]','[\"豆角可以用同季的替代品，用量保持不变。\"]',158.50,7.10,10.30,11.10,3.20,476.70,2,1,4.17,18,0.6078,15,659,'2026-05-31 16:47:55',0,'2026-05-31 16:47:55','2026-10-02 01:40:23'),(1900000000000000020,'蚝油生菜','蚝油生菜',NULL,1,NULL,1,4,'清淡',1,5,5,0,'生菜大火快炒，清淡，是一道很稳的家常下饭菜。','[{\"no\": 1, \"text\": \"生菜洗净切好，大蒜切配齐备用。\"}, {\"no\": 2, \"text\": \"锅烧热倒油，下蒜末和姜片爆出香味。\"}, {\"no\": 3, \"text\": \"倒入生菜大火翻炒至断生。\"}, {\"no\": 4, \"text\": \"加入大蒜，沿锅边淋入蚝油和生抽，翻炒均匀。\"}, {\"no\": 5, \"text\