{\"no\": 1, \"text\": \"三文鱼洗净擦干水分，用黑胡椒腌 15 分钟。\"}, {\"no\": 2, \"text\": \"平底锅倒油烧至六成热。\"}, {\"no\": 3, \"text\": \"放入三文鱼，中小火煎到一面定型。\"}, {\"no\": 4, \"text\": \"翻面继续煎 3 分钟，煎至两面金黄。\"}, {\"no\": 5, \"text\": \"出锅吸掉多余油，撒上葱花即可。\"}]','[\"盐\", \"黑胡椒\", \"柠檬\", \"蜂蜜\"]','[\"平底锅\"]','[\"食材表面擦干再下锅，不容易溅油。\", \"一面定型再翻，别急着动它。\"]','[\"三文鱼可以用同季的替代品，用量保持不变。\"]',226.40,26.00,11.90,3.90,0.30,488.10,2,1,4.41,17,0.6566,7,328,'2026-04-15 17:50:31',0,'2026-04-15 17:50:31','2026-10-02 01:40:23'),(1900000000000000443,'葱油饼','葱油饼',NULL,1,NULL,1,4,'酥脆',2,30,20,0,'面粉煎到两面金黄，外酥里嫩，配饭配酒都合适。','[{\"no\": 1, \"text\": \"面粉洗净擦干水分，用芝麻油腌 15 分钟。\"}, {\"no\": 2, \"text\": \"平底锅倒油烧至六成热。\"}, {\"no\": 3, \"text\": \"放入面粉，中小火煎到一面定型。\"}, {\"no\": 4, \"text\": \"翻面继续煎 6 分钟，煎至两面金黄。\"}, {\"no\": 5, \"text\": \"出锅吸掉多余油，撒上葱即可。\"}]','[\"盐\", \"芝麻油\"]','[\"平底锅\"]','[\"食材表面擦干再下锅，不容易溅油。\", \"一面定型再翻，别急着动它。\"]','[\"面粉可以用同季的替代品，用量保持不变。\"]',275.20,8.70,2.40,56.50,1.80,199.90,2,1,4.36,25,0.6908,18,860,'2026-06-11 00:45:22',0,'2026-06-11 00:45:22','2026-10-02 01:40:23'),(1900000000000000448,'凉拌黄瓜','凉拌黄瓜',NULL,1,NULL,1,3,'爽脆',1,8,5,1,'凉拌黄瓜爽脆开胃，不用开火也能端上桌。','[{\"no\": 1, \"text\": \"黄瓜洗净，按纹理切好。\"}, {\"no\": 2, \"text\": \"锅中水烧开，黄瓜焯 30 秒立刻捞出。\"}, {\"no\": 3, \"text\": \"过一遍凉开水，沥干后装盘。\"}, {\"no\": 4, \"text\": \"醋和生抽调成料汁。\"}, {\"no\": 5, \"text\": \"淋上料汁拌匀，静置 5 分钟入味即可。\"}]','[\"醋\", \"生抽\", \"芝麻油\", \"盐\"]','[\"拌盆\"]','[\"焯水后过一遍凉开水，口感更脆。\", \"料汁吃之前再淋，放久了会出水。\"]','[\"黄瓜可以用同季的替代品，用量保持不变。\"]',40.30,1.30,1.90,4.80,0.60,466.90,2,1,4.00,19,0.5779,9,344,'2026-04-16 14:54:00',0,'2026-04-16 14:54:00','2026-10-02 01:40:23'),(1900000000000000455,'拍黄瓜','拍黄瓜',NULL,1,NULL,1,4,'爽口',1,6,5,1,'拍黄瓜爽脆开胃，不用开火也能端上桌。','[{\"no\": 1, \"text\": \"黄瓜洗净，按纹理切好。\"}, {\"no\": 2, \"text\": \"锅中水烧开，黄瓜焯 30 秒立刻捞出。\"}, {\"no\": 3, \"text\": \"过一遍凉开水，沥干后装盘。\"}, {\"no\": 4, \"text\": \"醋和生抽调成料汁。\"}, {\"no\": 5, \"text\": \"淋上料汁拌匀，静置 5 分钟入味即可。\"}]','[\"醋\", \"生抽\", \"盐\", \"辣椒酱\"]','[\"拌盆\"]','[\"焯水后过一遍凉开水，口感更脆。\", \"料汁吃之前再淋，放久了会出水。\"]','[\"黄瓜可以用同季的替代品，用量保持不变。\"]',23.